{"command":"cd /workspace && python3 - <<'PY'
import wave, numpy as np
w=wave.open('/workspace/pitch.wav','rb'); n=w.getnframes(); sr=w.getframerate(); d=np.frombuffer(w.readframes(n),dtype=np.int16).reshape(-1,w.getnchannels()).astype(float)
print(sr,n,d.shape)
for ch in range(d.shape[1]):
    x=d[:,ch]
    # energy per 0.1s
    for i in range(0,384,48):
        seg=x[i*sr//100:(i+10)*sr//100]
        if np.max(np.abs(seg))>100:
            f=np.fft.rfftfreq(len(seg),1/sr); m=np.abs(np.fft.rfft(seg*np.hanning(len(seg)))); print(ch, i/100, f[m.argmax()], np.max(np.abs(seg)))
PY"}

