# ---------------- composer ----------------
class Composer:
    def __init__(self, patterns=15, rows=64, channels=12):
        self.patterns = patterns
        self.rows = rows
        self.channels = channels
        self.notes = []   # (p,r,ch,note,inst,vol,effect,param)
        self.ends = []    # (p,r,ch)
        self.note_starts = set()

    def note(self, p, r, ch, note, inst, vol, effect=0, param=0, dur=None, end=True):
        if not (0 <= p < self.patterns and 0 <= r < self.rows and 0 <= ch < self.channels):
            return
        self.notes.append((p,r,ch,note,inst,vol,effect,param))
        self.note_starts.add((p,r,ch))
        if dur is not None and end:
            er = r + dur
            if er >= self.rows:
                er = self.rows - 1
            if er > r:
                self.ends.append((p,er,ch))

    def drum(self, p, r, ch, inst, vol, effect=0, param=0):
        self.note(p,r,ch,'C-4',inst,vol,effect,param,dur=None)

    def generate_cells(self):
        cells = {}
        for (p,r,ch,note,inst,vol,eff,par) in self.notes:
            cells[(p,r,ch)] = {'note':note,'instrument':inst,'volume':vol,'effect':eff,'effect_param':par}
        for (p,r,ch) in self.ends:
            if (p,r,ch) not in self.note_starts:
                cells[(p,r,ch)] = {'note':0,'instrument':0,'volume':0,'effect':0,'effect_param':0}
        # channel resets at row 0 of each pattern for channels without a note start
        for p in range(self.patterns):
            for ch in range(self.channels):
                if (p,0,ch) not in self.note_starts:
                    cells[(p,0,ch)] = {'note':0,'instrument':0,'volume':0,'effect':0,'effect_param':0}
        return cells

    def cells_to_calls(self):
        cells = self.generate_cells()
        calls = []
        for (p,r,ch), c in sorted(cells.items()):
            calls.append({'name':'pattern_set_cell','arguments':{
                'pattern':p,'row':r,'channel':ch,
                'note':c['note'],'instrument':c['instrument'],'volume':c['volume'],
                'effect':c['effect'],'effect_param':c['effect_param']
            }})
        return calls

# ---------------- drums ----------------
def write_drums(c, p, section, bar):
    base = bar*16
    # Kick
    if section == 'intro':
        kicks = [(0,48),(8,40)]
        if bar == 3: kicks += [(12,44)]
    elif section == 'build':
        kicks = [(0,56),(4,52),(8,56),(12,52)]
        if bar in (1,3): kicks += [(14,50)]
    elif section == 'main':
        kicks = [(0,62),(4,56),(8,62),(12,56)]
        if bar in (1,3): kicks += [(14,54)]
    elif section == 'break':
        kicks = [(0,46),(8,38)]
        if bar == 3: kicks += [(12,42)]
    elif section == 'climax':
        kicks = [(0,64),(4,60),(8,64),(12,60)]
        if bar in (1,3): kicks += [(6,56),(14,58)]
        if bar == 3: kicks += [(2,60)]
    elif section == 'outro':
        kicks = [(0,44),(8,36)]
        if bar == 3: kicks += [(12,40)]
    else:
        kicks = []
    for rr,v in kicks:
        c.drum(p, base+rr, 0, 1, v)

    # Snare / clap
    if section in ('build','main','climax'):
        for rr in (4,12):
            c.drum(p, base+rr, 1, 2, 46 if section != 'climax' else 50)
            c.drum(p, base+rr, 2, 3, 38)
        if section in ('build','main') and bar in (1,3):
            # tom fill
            c.drum(p, base+13, 1, 28, 40)
            c.drum(p, base+14, 1, 29, 42)
            c.drum(p, base+15, 1, 2, 44)
        if section == 'climax' and bar in (1,3):
            c.drum(p, base+7, 1, 2, 30)
            c.drum(p, base+15, 1, 2, 34)
    elif section == 'break':
        for rr in (4,12):
            c.drum(p, base+rr, 2, 3, 34)
    elif section == 'outro':
        for rr in (4,12):
            c.drum(p, base+rr, 1, 2, 32)
            c.drum(p, base+rr, 2, 3, 26)
    elif section == 'intro':
        if bar == 3:
            c.drum(p, base+12, 1, 2, 30)

    # Closed hat / shaker
    if section in ('build','main','climax'):
        for i in range(16):
            v = 30 if i % 4 == 0 else (20 if i % 2 == 0 else 14)
            c.drum(p, base+i, 3, 4, v)
    elif section == 'intro':
        for i in range(0,16,2):
            c.drum(p, base+i, 3, 30, 16)
    elif section == 'break':
        for i in range(0,16,2):
            c.drum(p, base+i, 3, 30, 12)
    elif section == 'outro':
        for i in range(0,16,2):
            c.drum(p, base+i, 3, 4, 16)

    # Open hat / ride
    if section in ('build','main','climax'):
        for rr in (2,6,10,14):
            c.drum(p, base+rr, 4, 5, 24 if section != 'climax' else 28)
        if section == 'main' or section == 'climax':
            for rr in (0,4,8,12):
                c.drum(p, base+rr, 4, 6, 20)
    elif section == 'break':
        for rr in (6,14):
            c.drum(p, base+rr, 4, 5, 14)
    elif section == 'intro':
        if bar == 3:
            c.drum(p, base+14, 4, 5, 12)
    elif section == 'outro':
        for rr in (6,14):
            c.drum(p, base+rr, 4, 5, 12)

# ---------------- bass ----------------
def write_bass(c, p, chord, bar, section):
    base = bar*16
    root = CHORDS[chord]['bass']
    passing = CHORDS[chord]['pass']
    if section == 'intro':
        c.note(p, base, 5, root, 9, 34, dur=16)
        c.note(p, base, 11, root, 10, 26, dur=16)
    elif section == 'build':
        for rr in (0,2,4,6,8,10,12,14):
            note = root if rr not in (4,12) else root.replace('-2','-3')
            vol = 44 if rr % 4 == 0 else 38
            c.note(p, base+rr, 5, note, 9, vol, dur=2)
        c.note(p, base+14, 5, passing, 9, 38, dur=2)
    elif section == 'main':
        for rr in (0,2,4,6,8,10,12,14):
            note = root if rr not in (4,12) else root.replace('-2','-3')
            vol = 50 if rr % 4 == 0 else 42
            c.note(p, base+rr, 5, note, 9, vol, dur=2)
        c.note(p, base+14, 5, passing, 9, 42, dur=2)
    elif section == 'climax':
        for i in range(16):
            note = root
            if i % 4 == 2: note = root.replace('-2','-3')
            vol = 54 if i % 4 == 0 else (46 if i % 2 == 0 else 38)
            c.note(p, base+i, 5, note, 9, vol, dur=1)
        if bar == 3:
            c.note(p, base+15, 5, passing, 9, 42, dur=1)
    elif section == 'break':
        c.note(p, base, 5, root, 9, 34, dur=8)
        c.note(p, base+8, 5, root, 9, 30, dur=8)
        c.note(p, base, 11, root, 10, 24, dur=16)
    elif section == 'outro':
        c.note(p, base, 5, root, 9, 30, dur=16)
        c.note(p, base, 11, root, 10, 20, dur=16)

# ---------------- arps ----------------
def write_arps(c, p, chord, bar, section):
    base = bar*16
    pat = ARP_PATTERNS[chord]
    if section == 'intro':
        for i,n in enumerate(pat):
            c.note(p, base+i, 6, n, 13, 20, dur=1)
            if i < 15:
                c.note(p, base+i+1, 7, n, 14, 14, dur=1)
    elif section == 'build':
        for i,n in enumerate(pat):
            c.note(p, base+i, 6, n, 13, 30, dur=1)
            if i < 15:
                c.note(p, base+i+1, 7, n, 14, 20, dur=1)
    elif section in ('main','climax'):
        for i,n in enumerate(pat):
            c.note(p, base+i, 6, n, 13, 32, dur=1)
            if i < 15:
                c.note(p, base+i+1, 7, n, 14, 22, dur=1)
    elif section == 'break':
        for i in range(0,16,2):
            n = pat[i]
            c.note(p, base+i, 6, n, 13, 16, dur=2)
            if i < 14:
                c.note(p, base+i+1, 7, n, 14, 11, dur=2)
    elif section == 'outro':
        for i in range(0,16,2):
            n = pat[i]
            c.note(p, base+i, 6, n, 13, 16, dur=2)
            if i < 14:
                c.note(p, base+i+1, 7, n, 14, 10, dur=2)

# ---------------- pad ----------------
def pad_inst(chord, section):
    q = CHORDS[chord]['quality']
    if section in ('intro','break'):
        if q == 'min': return 17
        if q == 'maj': return 18
    if section == 'climax' and chord == 'G':
        return 19
    if q == 'min': return 15
    if q == 'maj': return 16
    return 16

def write_pad(c, p, chord, bar, section):
    base = bar*16
    inst = pad_inst(chord, section)
    root = CHORDS[chord]['pad']
    vol = 34 if section not in ('intro','break') else 40
    c.note(p, base, 9, root, inst, vol, dur=16)

# ---------------- stabs ----------------
def stab_inst(chord, section):
    q = CHORDS[chord]['quality']
    if section == 'climax' and chord == 'G':
        return 24
    if q == 'min': return 21
    if q == 'maj': return 22
    return 22

def write_stabs(c, p, chord, bar, section):
    if section not in ('build','main','climax'):
        return
    base = bar*16
    inst = stab_inst(chord, section)
    root = CHORDS[chord]['stab']
    for rr in (2,6,10,14):
        vol = 30 if section != 'climax' else 34
        if section == 'build' and bar == 0:
            vol = 26
        c.note(p, base+rr, 10, root, inst, vol, dur=2)

# ---------------- lead ----------------
def transpose_melody(mel, semitones):
    # simple note transposition for melodies: parse note names
    names = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
    def tr(note):
        if not note: return note
        # parse e.g. 'G#-5' or 'A-4'
        if '#' in note:
            name = note[:2]; octv = int(note[3:])
        else:
            name = note[0]; octv = int(note[2:])
        idx = names.index(name)
        total = octv*12 + idx + semitones
        new_oct = total // 12
        new_idx = total % 12
        return names[new_idx] + '-' + str(new_oct)
    return [[(r,tr(n),d) for (r,n,d) in bar] for bar in mel]

def write_lead(c, p, melody, bar, vol=48, octave=0, echo=True, effect_vib=True):
    base = bar*16
    for (r,n,d) in melody[bar]:
        nn = n
        if octave:
            nn = transpose_melody([[(r,n,d)]], octave)[0][0][1]
        eff = 0
        par = 0
        if effect_vib and d >= 4:
            eff = 0x04; par = 0x52
        c.note(p, base+r, 8, nn, 11, vol, effect=eff, param=par, dur=d)
        if echo and r+3 < 16:
            c.note(p, base+r+3, 11, nn, 31, 20, effect=0, param=0, dur=max(1,d-1))

# ---------------- fx ----------------
def write_fx(c, p, section, bar):
    base = bar*16
    if section == 'intro' and bar == 3:
        c.note(p, base+0, 10, 'C-4', 8, 38, dur=16)  # reverse crash
    if section == 'build' and bar == 0:
        c.note(p, base, 10, 'C-4', 25, 44, dur=32)  # riser
    if section == 'build' and bar == 3:
        c.note(p, base+0, 10, 'C-4', 8, 38, dur=16)  # reverse crash
        c.note(p, base+8, 10, 'C-4', 27, 34, dur=8)  # sub drop
    if section in ('main','climax') and bar == 0:
        c.note(p, base, 10, 'C-4', 7, 40, dur=8)     # crash
    if section in ('main','climax') and bar == 3:
        c.note(p, base+0, 10, 'C-4', 26, 34, dur=8)  # downlifter
    if section == 'break' and bar == 3:
        c.note(p, base+0, 10, 'C-4', 8, 36, dur=16)  # reverse crash
    if section == 'outro' and bar == 3:
        c.note(p, base+0, 10, 'C-4', 8, 40, dur=16)  # reverse crash
        c.note(p, base+8, 10, 'C-4', 27, 30, dur=8)  # sub drop

# ---------------- build song ----------------
def build_song():
    c = Composer(patterns=15, rows=64, channels=12)

    # Pattern 0: Intro A (Am F C G)
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 0, ch, bar, 'intro')
        write_bass(c, 0, ch, bar, 'intro')
        write_arps(c, 0, ch, bar, 'intro')
        write_drums(c, 0, 'intro', bar)
        write_fx(c, 0, 'intro', bar)
    write_lead(c, 0, MEL_INTRO, 2, vol=36, echo=True)
    write_lead(c, 0, MEL_INTRO, 3, vol=38, echo=True)

    # Pattern 1: Intro B (Am F C G)
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 1, ch, bar, 'intro')
        write_bass(c, 1, ch, bar, 'intro')
        write_arps(c, 1, ch, bar, 'intro')
        write_drums(c, 1, 'intro', bar)
        write_fx(c, 1, 'intro', bar)
    write_lead(c, 1, MEL_A, 0, vol=38, echo=True)
    write_lead(c, 1, MEL_A, 1, vol=38, echo=True)
    write_lead(c, 1, MEL_A, 2, vol=40, echo=True)
    write_lead(c, 1, MEL_A, 3, vol=42, echo=True)

    # Pattern 2: Build A (Dm Am E E)
    prog = ['Dm','Am','E','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 2, ch, bar, 'build')
        write_bass(c, 2, ch, bar, 'build')
        write_arps(c, 2, ch, bar, 'build')
        write_drums(c, 2, 'build', bar)
        write_fx(c, 2, 'build', bar)
        write_stabs(c, 2, ch, bar, 'build')
    write_lead(c, 2, MEL_BUILD, 0, vol=42, echo=True)
    write_lead(c, 2, MEL_BUILD, 1, vol=44, echo=True)
    write_lead(c, 2, MEL_BUILD, 2, vol=46, echo=True)
    write_lead(c, 2, MEL_BUILD, 3, vol=48, echo=True)
    # snare roll last bar
    for i in range(16):
        c.drum(2, 48+i, 1, 2, 20 + i*2)

    # Pattern 3: Main A1
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 3, ch, bar, 'main')
        write_bass(c, 3, ch, bar, 'main')
        write_arps(c, 3, ch, bar, 'main')
        write_drums(c, 3, 'main', bar)
        write_fx(c, 3, 'main', bar)
        write_stabs(c, 3, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 3, MEL_A, bar, vol=48, echo=True)

    # Pattern 4: Main A2
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 4, ch, bar, 'main')
        write_bass(c, 4, ch, bar, 'main')
        write_arps(c, 4, ch, bar, 'main')
        write_drums(c, 4, 'main', bar)
        write_fx(c, 4, 'main', bar)
        write_stabs(c, 4, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 4, MEL_A_VAR, bar, vol=50, echo=True)

    # Pattern 5: Main B1
    prog = ['Dm','Am','E','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 5, ch, bar, 'main')
        write_bass(c, 5, ch, bar, 'main')
        write_arps(c, 5, ch, bar, 'main')
        write_drums(c, 5, 'main', bar)
        write_fx(c, 5, 'main', bar)
        write_stabs(c, 5, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 5, MEL_B, bar, vol=50, echo=True)

    # Pattern 6: Main B2
    prog = ['Dm','Am','E','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 6, ch, bar, 'main')
        write_bass(c, 6, ch, bar, 'main')
        write_arps(c, 6, ch, bar, 'main')
        write_drums(c, 6, 'main', bar)
        write_fx(c, 6, 'main', bar)
        write_stabs(c, 6, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 6, MEL_B, bar, vol=52, echo=True)
    # add octave-up layer in last 2 bars
    for bar in (2,3):
        write_lead(c, 6, MEL_B, bar, vol=28, octave=12, echo=False)

    # Pattern 7: Breakdown (F G Em Am)
    prog = ['F','G','Em','Am']
    for bar,ch in enumerate(prog):
        write_pad(c, 7, ch, bar, 'break')
        write_bass(c, 7, ch, bar, 'break')
        write_arps(c, 7, ch, bar, 'break')
        write_drums(c, 7, 'break', bar)
        write_fx(c, 7, 'break', bar)
    for bar in range(4):
        write_lead(c, 7, MEL_BREAK, bar, vol=44, echo=False)
    # counter melody on channel 11
    for bar in range(4):
        for (r,n,d) in COUNTER_BREAK[bar]:
            c.note(7, bar*16+r, 11, n, 31, 24, dur=d)

    # Pattern 8: Build B (F G Am E)
    prog = ['F','G','Am','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 8, ch, bar, 'build')
        write_bass(c, 8, ch, bar, 'build')
        write_arps(c, 8, ch, bar, 'build')
        write_drums(c, 8, 'build', bar)
        write_fx(c, 8, 'build', bar)
        write_stabs(c, 8, ch, bar, 'build')
    write_lead(c, 8, MEL_BUILD, 0, vol=44, echo=True)
    write_lead(c, 8, MEL_BUILD, 1, vol=46, echo=True)
    write_lead(c, 8, MEL_BUILD, 2, vol=48, echo=True)
    write_lead(c, 8, MEL_BUILD, 3, vol=50, echo=True)
    for i in range(16):
        c.drum(8, 48+i, 1, 2, 22 + i*2)

    # Pattern 9: Main A3
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 9, ch, bar, 'main')
        write_bass(c, 9, ch, bar, 'main')
        write_arps(c, 9, ch, bar, 'main')
        write_drums(c, 9, 'main', bar)
        write_fx(c, 9, 'main', bar)
        write_stabs(c, 9, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 9, MEL_A, bar, vol=52, echo=True)
        write_lead(c, 9, MEL_A, bar, vol=26, octave=12, echo=False)

    # Pattern 10: Main A4
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 10, ch, bar, 'main')
        write_bass(c, 10, ch, bar, 'main')
        write_arps(c, 10, ch, bar, 'main')
        write_drums(c, 10, 'main', bar)
        write_fx(c, 10, 'main', bar)
        write_stabs(c, 10, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 10, MEL_A_VAR, bar, vol=52, echo=True)
        write_lead(c, 10, MEL_A_VAR, bar, vol=26, octave=12, echo=False)

    # Pattern 11: Main B3
    prog = ['Dm','Am','E','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 11, ch, bar, 'main')
        write_bass(c, 11, ch, bar, 'main')
        write_arps(c, 11, ch, bar, 'main')
        write_drums(c, 11, 'main', bar)
        write_fx(c, 11, 'main', bar)
        write_stabs(c, 11, ch, bar, 'main')
    for bar in range(4):
        write_lead(c, 11, MEL_B, bar, vol=52, echo=True)
        write_lead(c, 11, MEL_B, bar, vol=28, octave=12, echo=False)

    # Pattern 12: Climax (Am F C G)
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 12, ch, bar, 'climax')
        write_bass(c, 12, ch, bar, 'climax')
        write_arps(c, 12, ch, bar, 'climax')
        write_drums(c, 12, 'climax', bar)
        write_fx(c, 12, 'climax', bar)
        write_stabs(c, 12, ch, bar, 'climax')
    for bar in range(4):
        write_lead(c, 12, MEL_A, bar, vol=54, echo=True)
        write_lead(c, 12, MEL_A, bar, vol=30, octave=12, echo=False)
    # extra tom fill in last bar
    c.drum(12, 61, 1, 28, 42)
    c.drum(12, 62, 1, 29, 44)
    c.drum(12, 63, 1, 2, 46)

    # Pattern 13: Outro A (Am F C G)
    prog = ['Am','F','C','G']
    for bar,ch in enumerate(prog):
        write_pad(c, 13, ch, bar, 'outro')
        write_bass(c, 13, ch, bar, 'outro')
        write_arps(c, 13, ch, bar, 'outro')
        write_drums(c, 13, 'outro', bar)
        write_fx(c, 13, 'outro', bar)
    for bar in range(4):
        write_lead(c, 13, MEL_OUTRO, bar, vol=40, echo=True)

    # Pattern 14: Outro B (F G Am E)
    prog = ['F','G','Am','E']
    for bar,ch in enumerate(prog):
        write_pad(c, 14, ch, bar, 'outro')
        write_bass(c, 14, ch, bar, 'outro')
        write_arps(c, 14, ch, bar, 'outro')
        write_drums(c, 14, 'outro', bar)
        write_fx(c, 14, 'outro', bar)
    for bar in range(4):
        write_lead(c, 14, MEL_OUTRO, bar, vol=38, echo=True)
    # final sustained E and turnaround
    c.note(14, 48, 9, 'E-3', 20, 36, dur=16)
    c.note(14, 48, 11, 'E-5', 31, 22, dur=16)
    c.note(14, 60, 0, 'C-4', 1, 30, dur=4)

    return c

# ---------------- module creation ----------------
def create_module(c):
    print('creating module...', flush=True)
    ft2_call('module_new', {'channels':12, 'name':'Neon Cipher'})
    ft2_call('song_set', {'bpm':155, 'speed':6, 'length':15, 'loop_start':0, 'channels':12})
    # pattern lengths
    calls = []
    for p in range(15):
        calls.append({'name':'pattern_set_length','arguments':{'pattern':p,'rows':64}})
    for pos in range(15):
        calls.append({'name':'order_set','arguments':{'position':pos,'pattern':pos}})
    ft2_batch(calls, chunk=100)

    # samples
    samples = build_all()
    # instrument order
    inst_order = [
        (1,'Kick'),(2,'Snare'),(3,'Clap'),(4,'Closed Hat'),(5,'Open Hat'),(6,'Ride'),
        (7,'Crash'),(8,'Reverse Crash'),(9,'Bass'),(10,'Sub Bass'),(11,'Lead'),
        (12,'Lead Pluck'),(13,'Arp L'),(14,'Arp R'),(15,'Pad Minor'),(16,'Pad Major'),
        (17,'Pad Min7'),(18,'Pad Maj7'),(19,'Pad Sus4'),(20,'Pad Dim'),(21,'Stab Minor'),
        (22,'Stab Major'),(23,'Stab Min7'),(24,'Stab Sus4'),(25,'Riser'),(26,'Downlifter'),
        (27,'Sub Drop'),(28,'Tom Low'),(29,'Tom High'),(30,'Shaker'),(31,'Lead Echo')
    ]
    sample_map = {
        'Kick':'Kick','Snare':'Snare','Clap':'Clap','Closed Hat':'Closed Hat','Open Hat':'Open Hat',
        'Ride':'Ride','Crash':'Crash','Reverse Crash':'Reverse Crash','Bass':'Bass','Sub Bass':'Sub Bass',
        'Lead':'Lead','Lead Pluck':'Lead Pluck','Arp L':'Arp','Arp R':'Arp',
        'Pad Minor':'Pad Minor','Pad Major':'Pad Major','Pad Min7':'Pad Min7','Pad Maj7':'Pad Maj7',
        'Pad Sus4':'Pad Sus4','Pad Dim':'Pad Dim','Stab Minor':'Stab Minor','Stab Major':'Stab Major',
        'Stab Min7':'Stab Min7','Stab Sus4':'Stab Sus4','Riser':'Riser','Downlifter':'Downlifter',
        'Sub Drop':'Sub Drop','Tom Low':'Tom Low','Tom High':'Tom High','Shaker':'Shaker',
        'Lead Echo':'Lead'
    }
    pans = {
        'Kick':128,'Snare':128,'Clap':110,'Closed Hat':160,'Open Hat':160,'Ride':150,
        'Crash':128,'Reverse Crash':128,'Bass':128,'Sub Bass':128,'Lead':128,'Lead Pluck':128,
        'Arp L':64,'Arp R':192,'Pad Minor':128,'Pad Major':128,'Pad Min7':128,'Pad Maj7':128,
        'Pad Sus4':128,'Pad Dim':128,'Stab Minor':128,'Stab Major':128,'Stab Min7':128,
        'Stab Sus4':128,'Riser':128,'Downlifter':128,'Sub Drop':128,'Tom Low':110,'Tom High':150,
        'Shaker':170,'Lead Echo':200
    }
    # create instruments first
    calls = []
    for inst, name in inst_order:
        calls.append({'name':'instrument_set','arguments':{'instrument':inst,'name':name}})
    ft2_batch(calls, chunk=100)

    # create samples in chunks to keep batch files manageable
    print('creating samples...', flush=True)
    sample_calls = []
    for inst, name in inst_order:
        pcm = samples[sample_map[name]]
        b = base64.b64encode(pcm.tobytes()).decode()
        sample_calls.append({'name':'sample_create_from_pcm','arguments':{
            'instrument':inst,'sample':0,'pcm':b,'encoding':'float32','name':name}})
    ft2_batch(sample_calls, chunk=4)

    # set sample metadata
    print('setting sample metadata...', flush=True)
    meta_calls = []
    for inst, name in inst_order:
        meta_calls.append({'name':'sample_set','arguments':{
            'instrument':inst,'sample':0,'name':name,'volume':64,'panning':pans[name],
            'finetune':103,'relative_note':28,'loop_start':0,'loop_length':0,'flags':16}})
    ft2_batch(meta_calls, chunk=100)

    # write patterns
    print('writing patterns...', flush=True)
    cells_calls = c.cells_to_calls()
    print(f'{len(cells_calls)} cells', flush=True)
    ft2_batch(cells_calls, chunk=400)

    # save
    print('saving...', flush=True)
    ft2_call('module_save', {'path':'/workspace/tune_build/tune.xm','format':'xm'})
    print('done', flush=True)

if __name__ == '__main__':
    c = build_song()
    print('notes', len(c.notes), 'ends', len(c.ends), 'cells', len(c.generate_cells()))
    create_module(c)
