# ---------------- FT2 helpers ----------------
def ft2_call(tool, args):
    cmd = ['ft2', 'call', tool, json.dumps(args, separators=(',', ':'))]
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(f"ft2 call {tool} failed: {r.stdout}\n{r.stderr}")
    return r.stdout

def ft2_batch(calls, chunk=400, tmpdir='/workspace/tune_build/batches'):
    os.makedirs(tmpdir, exist_ok=True)
    for i in range(0, len(calls), chunk):
        part = calls[i:i+chunk]
        path = os.path.join(tmpdir, f'batch_{i//chunk:04d}.json')
        with open(path, 'w') as f:
            json.dump(part, f, separators=(',', ':'))
        cmd = ['ft2', 'batch', path]
        r = subprocess.run(cmd, capture_output=True, text=True)
        if r.returncode != 0:
            raise RuntimeError(f"ft2 batch {path} failed: {r.stdout}\n{r.stderr}")
